[{"order":1,"type":"heading","text":"Access Modifiers in Java: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"Access modifiers are keywords in Java that control the visibility and accessibility of classes, methods, constructors, and variables. They determine from where these elements can be accessed. Java provides four access modifiers: `public`, `private`, `protected`, and default (package-private)."},{"order":3,"type":"subheading","text":"1. Public Access Modifier"},{"order":4,"type":"paragraph","text":"The `public` access modifier is the most permissive. Members declared as `public` are accessible from anywhere, both within the same class, other classes in the same package, and classes in different packages. There are no restrictions on access."},{"order":5,"type":"code","text":"public class PublicExample {
    public int publicVariable = 10;

    public void publicMethod() {
        System.out.println("This is a public method.");
    }
}"},{"order":6,"type":"code","text":"public class AnotherClass {
    public static void main(String[] args) {
        PublicExample obj = new PublicExample();
        System.out.println("Public variable: " + obj.publicVariable); // Accessible
        obj.publicMethod(); // Accessible
    }
}"},{"order":7,"type":"subheading","text":"2. Private Access Modifier"},{"order":8,"type":"paragraph","text":"The `private` access modifier is the most restrictive. Members declared as `private` are only accessible within the class in which they are declared. They are not accessible from any other class, not even subclasses or classes within the same package. This is often used for data hiding and encapsulation."},{"order":9,"type":"code","text":"public class PrivateExample {
    private int privateVariable = 20;

    private void privateMethod() {
        System.out.println("This is a private method.");
    }

    public void accessPrivate() {
        System.out.println("Accessing private variable from within the class: " + privateVariable);
        privateMethod();
    }
}"},{"order":10,"type":"code","text":"public class AnotherClass {
    public static void main(String[] args) {
        PrivateExample obj = new PrivateExample();
        // System.out.println(obj.privateVariable); // Compilation error: privateVariable has private access in PrivateExample
        // obj.privateMethod(); // Compilation error: privateMethod() has private access in PrivateExample
        obj.accessPrivate(); // This is how you can access private members indirectly
    }
}"},{"order":11,"type":"subheading","text":"3. Protected Access Modifier"},{"order":12,"type":"paragraph","text":"The `protected` access modifier provides a balance between `public` and `private`. Members declared as `protected` are accessible within the same package and by subclasses, even if they are in a different package. If a class is not a subclass, it cannot access `protected` members from a different package."},{"order":13,"type":"code","text":"package package1;

public class ProtectedExample {
    protected int protectedVariable = 30;

    protected void protectedMethod() {
        System.out.println("This is a protected method.");
    }
}"},{"order":14,"type":"code","text":"package package1;

public class SamePackageClass {
    public static void main(String[] args) {
        ProtectedExample obj = new ProtectedExample();
        System.out.println("Protected variable (same package): " + obj.protectedVariable); // Accessible
        obj.protectedMethod(); // Accessible
    }
}"},{"order":15,"type":"code","text":"package package2;

import package1.ProtectedExample;

public class SubclassExample extends ProtectedExample {
    public static void main(String[] args) {
        SubclassExample obj = new SubclassExample();
        System.out.println("Protected variable (subclass, different package): " + obj.protectedVariable); // Accessible
        obj.protectedMethod(); // Accessible
    }
}"},{"order":16,"type":"code","text":"package package2;

import package1.ProtectedExample;

public class AnotherClass {
    public static void main(String[] args) {
        ProtectedExample obj = new ProtectedExample();
        // System.out.println(obj.protectedVariable); // Compilation error: protectedVariable has protected access in ProtectedExample
        // obj.protectedMethod(); // Compilation error: protectedMethod() has protected access in ProtectedExample
    }
}"},{"order":17,"type":"subheading","text":"4. Default (Package-Private) Access Modifier"},{"order":18,"type":"paragraph","text":"When no access modifier is specified, it is known as the default or package-private access modifier. Members with default access are accessible only within the same package. They are not accessible from classes in different packages, even if they are subclasses."},{"order":19,"type":"code","text":"package package1;

class DefaultExample {
    int defaultVariable = 40; // No access modifier specified

    void defaultMethod() { // No access modifier specified
        System.out.println("This is a default method.");
    }
}"},{"order":20,"type":"code","text":"package package1;

public class SamePackageClass {
    public static void main(String[] args) {
        DefaultExample obj = new DefaultExample();
        System.out.println("Default variable (same package): " + obj.defaultVariable); // Accessible
        obj.defaultMethod(); // Accessible
    }
}"},{"order":21,"type":"code","text":"package package2;

import package1.DefaultExample;

public class AnotherClass {
    public static void main(String[] args) {
        // DefaultExample obj = new DefaultExample(); // Compilation error: DefaultExample is not public in package package1; cannot be accessed from outside package
        // System.out.println(obj.defaultVariable); // Compilation error
        // obj.defaultMethod(); // Compilation error
    }
}"},{"order":22,"type":"subheading","text":"Summary Table"},{"order":23,"type":"paragraph","text":"Here's a table summarizing the accessibility of each access modifier:"},{"order":24,"type":"bullet_point","text":"**Public:** Accessible from anywhere."},{"order":25,"type":"bullet_point","text":"**Private:** Accessible only within the same class."},{"order":26,"type":"bullet_point","text":"**Protected:** Accessible within the same package and by subclasses (even in different packages)."},{"order":27,"type":"bullet_point","text":"**Default (Package-Private):** Accessible only within the same package."},{"order":28,"type":"paragraph","text":"Choosing the appropriate access modifier is crucial for designing robust, maintainable, and secure Java applications. It helps in encapsulating data, controlling access, and promoting code reusability."}]
